{
  "project_id": "f5e7c12bee40408dbf36",
  "query": "with waiting as (select l.pid, l.locktype, l.mode, l.relation::regclass as relation, l.transactionid, l.granted, pg_blocking_pids(l.pid) as blockers from pg_locks l where not l.granted) select w.pid as blocked_pid, w.relation, w.locktype, w.mode as requested_mode, w.blockers, b.pid as blocker_pid, b.usename as blocker_user, b.application_name as blocker_app, b.state as blocker_state, b.xact_start as blocker_xact_start, age(now(), b.xact_start) as blocker_xact_age, b.query_start as blocker_query_start, age(now(), b.query_start) as blocker_query_age, left(b.query, 500) as blocker_query from waiting w cross join lateral unnest(w.blockers) as bp(pid) join pg_stat_activity b on b.pid = bp.pid where w.pid <> pg_backend_pid() order by b.xact_start nulls last;"
}

